SELECT *, AVG(amount) OVER w_hist AS method_avg_amount, ROW_NUMBER() OVER w_ordered AS event_seq, SUM(amount) OVER (PARTITION BY method ORDER BY amount ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_amount, NTILE(5) OVER (PARTITION BY order_id ORDER BY amount DESC, id ASC) AS amount_bucket FROM payments WINDOW w_hist AS (PARTITION BY method, status), w_ordered AS (PARTITION BY status ORDER BY paid_at ASC, id ASC)
